use lens_evals_sdk::setup::{self, InitOptions, Settings};
use rstest::{fixture, rstest};
use std::fs;
use tempfile::TempDir;

#[fixture]
fn root() -> TempDir {
    tempfile::tempdir().unwrap()
}
#[fixture]
fn options() -> InitOptions {
    InitOptions {
        dataset: Some("demo@1".into()),
        project: Some("demo".into()),
        base_url: Some("http://127.0.0.1:8765".into()),
        task: None,
        demo: false,
        action: "BerriAI/lens/src/sdk/action@preview".into(),
    }
}

#[rstest]
fn guided_setup_preserves_existing_configuration(root: TempDir, options: InitOptions) {
    fs::write(
        root.path().join("pyproject.toml"),
        "# keep my comment\n[project]\nname='agent'\n[tool.lens]\nevals='checks/'\n",
    )
    .unwrap();
    let mut values = ["demo@1", "demo", "http://127.0.0.1:8765", "agent:run"].into_iter();
    let options = InitOptions {
        dataset: None,
        project: None,
        base_url: None,
        ..options
    };
    setup::initialize_with(root.path(), options, true, &mut |_| {
        Ok(values.next().unwrap().into())
    })
    .unwrap();
    let config = Settings::load(root.path()).unwrap();
    assert_eq!(config.project, "demo");
    assert_eq!(config.evals, "checks/");
    assert!(
        fs::read_to_string(root.path().join("pyproject.toml"))
            .unwrap()
            .contains("# keep my comment")
    );
    assert!(root.path().join("checks/demo.py").exists());
}

#[rstest]
#[case::eval("evals/demo.py")]
#[case::workflow(".github/workflows/lens.yml")]
fn existing_files_are_untouched(root: TempDir, options: InitOptions, #[case] existing: &str) {
    let path = root.path().join(existing);
    fs::create_dir_all(path.parent().unwrap()).unwrap();
    fs::write(&path, "keep me").unwrap();
    assert!(setup::initialize_with(root.path(), options, false, &mut |_| unreachable!()).is_err());
    assert_eq!(fs::read_to_string(path).unwrap(), "keep me");
    assert!(!root.path().join("pyproject.toml").exists());
}

#[rstest]
#[case::invalid_dataset("Bad name", "agent:run")]
#[case::invalid_task("demo", "agent;print:run")]
fn rejects_invalid_input_before_writing(
    root: TempDir,
    options: InitOptions,
    #[case] dataset: &str,
    #[case] task: &str,
) {
    let options = InitOptions {
        dataset: Some(dataset.into()),
        task: Some(task.into()),
        ..options
    };
    assert!(setup::initialize_with(root.path(), options, false, &mut |_| unreachable!()).is_err());
    assert!(!root.path().join("pyproject.toml").exists());
}

#[rstest]
fn demo_has_no_ci_gate(root: TempDir, options: InitOptions) {
    let options = InitOptions {
        demo: true,
        ..options
    };
    setup::initialize_with(root.path(), options, false, &mut |_| unreachable!()).unwrap();
    assert!(root.path().join("evals/demo.py").exists());
    assert!(!root.path().join(".github/workflows/lens.yml").exists());
}

#[rstest]
#[case::scalar_tool("tool = 'text'")]
#[case::scalar_lens("[tool]\nlens = 7")]
#[case::malformed("[tool.lens")]
fn malformed_configuration_has_no_partial_writes(
    root: TempDir,
    options: InitOptions,
    #[case] config: &str,
) {
    fs::write(root.path().join("pyproject.toml"), config).unwrap();
    assert!(setup::initialize_with(root.path(), options, false, &mut |_| unreachable!()).is_err());
    assert_eq!(
        fs::read_to_string(root.path().join("pyproject.toml")).unwrap(),
        config
    );
    assert!(!root.path().join("evals").exists());
}

#[rstest]
#[case::keyword("agent:lambda")]
#[case::keyword_module("agent.with:run")]
fn keyword_imports_are_rejected(root: TempDir, options: InitOptions, #[case] task: &str) {
    assert!(
        setup::initialize_with(
            root.path(),
            InitOptions {
                task: Some(task.into()),
                ..options
            },
            false,
            &mut |_| unreachable!()
        )
        .is_err()
    );
    assert!(!root.path().join("pyproject.toml").exists());
}

#[rstest]
fn uv_workflow_uses_agent_environment(root: TempDir, options: InitOptions) {
    fs::write(root.path().join("uv.lock"), "").unwrap();
    setup::initialize_with(root.path(), options, false, &mut |_| unreachable!()).unwrap();
    let workflow = fs::read_to_string(root.path().join(".github/workflows/lens.yml")).unwrap();
    assert!(workflow.contains("uv sync --frozen"));
    assert!(workflow.contains("python: .venv/bin/python"));
}

#[rstest]
fn local_connections_do_not_change_public_settings(root: TempDir) {
    fs::write(root.path().join("pyproject.toml"), "[tool.lens]\nproject='agent'\n[tool.lens.connections.local]\nauth='none'\nbase_url_env='AGENT_URL'\n").unwrap();
    let settings = Settings::load(root.path()).unwrap();
    assert!(settings.connections.contains_key("local"));
    assert_eq!(
        serde_json::to_value(settings).unwrap(),
        serde_json::json!({"project":"agent","evals":"evals/","base_url":""})
    );
}

#[rstest]
#[case::named(vec!["lens", "eval", "--name", "saved"], 0)]
#[case::conflicting_path(vec!["lens", "eval", "evals/", "--name", "saved"], 2)]
#[case::conflicting_filter(vec!["lens", "eval", "--eval", "local", "--name", "saved"], 2)]
fn saved_name_is_distinct_from_local_discovery(#[case] arguments: Vec<&str>, #[case] code: u64) {
    let result = setup::parse(&arguments.into_iter().map(str::to_owned).collect::<Vec<_>>());
    assert_eq!(
        result
            .get("code")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or(0),
        code
    );
    if code == 0 {
        assert_eq!(result["eval_name"], "saved");
    }
}

import { screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { beforeEach, expect, it, vi } from "vitest";
import { renderWithProviders } from "../../../../tests/test-utils";
import { LensHostProvider, type LensHost } from "../../../host/LensHost";
import { copyToClipboard } from "../../../utils/dataUtils";
import { SetupAgentPrompt } from "./SetupAgentPrompt";

vi.mock("../../../utils/dataUtils", () => ({
  copyToClipboard: vi.fn().mockResolvedValue(true),
}));

beforeEach(() => vi.clearAllMocks());

it.each([
  [
    { analysis: "deployment", surface: "embedded" },
    "existing LiteLLM admin dashboard",
  ],
  [{ analysis: "deployment", surface: "standalone" }, "standalone Lens app"],
  [{}, "existing LiteLLM admin dashboard"],
] satisfies readonly (readonly [LensHost, string])[])(
  "copies the correct host context for %j",
  async (host, expected) => {
    const user = userEvent.setup();
    renderWithProviders(
      <LensHostProvider host={host}>
        <SetupAgentPrompt />
      </LensHostProvider>,
    );

    await user.click(screen.getByRole("button", { name: "Set it up for me" }));

    expect(copyToClipboard).toHaveBeenCalledWith(
      expect.stringContaining(expected),
      "Prompt copied",
    );
    expect(
      screen.getByRole("button", { name: "Set it up for me" }),
    ).toHaveTextContent("Prompt copied");
  },
);

it("copies complete instructions from the first screen and exposes the next conversation", async () => {
  const user = userEvent.setup();
  renderWithProviders(
    <SetupAgentPrompt
      goal="tracing"
      prominent
      connection={{
        connected: true,
        url: "https://lens.example",
        status: { storage_ready: true },
      }}
    />,
  );

  expect(screen.getByText("Claude Code", { exact: true })).toBeVisible();
  expect(screen.getByText(/The instructions help your coding agent/)).toHaveTextContent("run one real task");
  await user.click(
    screen.getByRole("button", { name: "Copy setup instructions" }),
  );
  expect(copyToClipboard).toHaveBeenCalledWith(
    expect.stringContaining("https://lens.example/v1/traces/receipt"),
    "Prompt copied",
  );
  expect(copyToClipboard).toHaveBeenCalledWith(
    expect.stringContaining(
      'Then ask: "What would you like to instrument next?"',
    ),
    "Prompt copied",
  );
  expect(
    screen.getByRole("button", { name: "Copy setup instructions" }),
  ).toHaveTextContent("Prompt copied");
});

import { fireEvent, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { renderWithLens, stubGateway } from "../../../../tests/lens-test-utils";
import {
  chooseSelectOption,
  testQueryClient,
} from "../../../../tests/test-utils";
import type { DatasetSummary } from "../datasets/types";
import { evalRun, summary } from "../evals/runs/testRuns";
import type { EvalDefinition, EvalRun } from "../evals/runs/types";
import { GitHubEvalSetupDialog } from "./GitHubEvalSetupDialog";

const agent = "qa-agent";
const repository = "lens-test/agent";
const repositoryUrl = `https://github.com/${repository}`;
const dataset: DatasetSummary = {
  id: "qa-dataset",
  name: "Regression cases",
  agent_name: agent,
  revision: 2,
  case_count: 4,
  updated_at: "2026-10-01T00:00:00Z",
};
const definition: EvalDefinition = {
  name: "agent-regressions",
  spec: {
    agent,
    dataset_id: dataset.id,
    revision: null,
    scorers: [{ kind: "task_completed" }],
    trials: 3,
    baseline: "main",
    gate: {
      regressions: 0,
      critical: 0,
      pass_rate: null,
      cost_per_case: null,
      min: {},
    },
    timeout_per_trial_ms: 1_200_000,
  },
  updated_at: "2026-10-01T00:00:00Z",
};
const otherEval: EvalDefinition = { ...definition, name: "agent-smoke" };
const otherAgent: EvalDefinition = {
  ...definition,
  name: "unrelated-agent-eval",
  spec: { ...definition.spec, agent: "another-agent" },
};
const run = (id: string, overrides: Partial<EvalRun> = {}) =>
  evalRun(id, {
    agent,
    eval: definition.name,
    ci_url: `${repositoryUrl}/actions/runs/123`,
    ...overrides,
  });

let gateway = stubGateway();
const serve =
  (runs: readonly EvalRun[] = []) =>
  (path: string) => {
    if (path === "/lens/evals") return [definition, otherEval, otherAgent];
    if (path === "/lens/datasets") return [dataset];
    if (path === "/lens/evals/runs") return runs;
    throw new Error(`Unexpected GET ${path}`);
  };
const change = (name: string, value: string) =>
  fireEvent.change(screen.getByRole("textbox", { name }), {
    target: { value },
  });
const prepare = async (user: ReturnType<typeof userEvent.setup>) => {
  await screen.findByRole("combobox", { name: "Eval to run" });
  change("GitHub repository", repository);
  change("Lens URL", "https://lens.example.test");
  await user.click(screen.getByRole("button", { name: "Continue" }));
};
const verify = async (user: ReturnType<typeof userEvent.setup>) => {
  await prepare(user);
  await user.click(
    screen.getByRole("button", { name: "I’ve added the workflow" }),
  );
  await waitFor(() =>
    expect(
      screen.getByRole("button", { name: "Check for PR eval" }),
    ).toBeEnabled(),
  );
};

beforeEach(() => {
  testQueryClient.clear();
  gateway = stubGateway();
  gateway.get.mockImplementation(serve());
});

describe("GitHub eval workflow setup", () => {
  it("chooses this agent’s eval and carries repository, runtime and dataset into reviewable setup files", async () => {
    const user = userEvent.setup();
    renderWithLens(
      <GitHubEvalSetupDialog agent={agent} onOpenChange={vi.fn()} />,
    );
    const selector = await screen.findByRole("combobox", {
      name: "Eval to run",
    });
    await user.click(selector);
    expect(
      screen.queryByRole("option", { name: otherAgent.name }),
    ).not.toBeInTheDocument();
    await user.click(screen.getByRole("option", { name: otherEval.name }));
    change("GitHub repository", `${repositoryUrl}.git`);
    change("Lens URL", "https://lens.example.test/");
    await user.click(screen.getByText("Agent runtime"));
    change("Existing eval task (optional)", "my_agent.evals:task");
    change("Install and start your agent (optional)", "npm ci");
