    await user.click(screen.getByRole("button", { name: "Check for PR eval" }));
    expect(
      await screen.findByRole("heading", { name: "PR eval received" }),
    ).toBeVisible();
    expect(
      screen.getByText(/Gate failed, review the result before merging/),
